const body = $input.first().json.body ?? $input.first().json;

const artist = body.artistName;
const service = body.service;
const styles = body.styles || [];
const images = body.images || [];
const dateCompleted = body.dateCompleted;

// styles[] -> hashtags, plus fixed tags (deterministic, not AI-generated)
const styleTags = styles.map((s) => '#' + String(s).toLowerCase().replace(/[^a-z0-9]+/g, ''));
const fixedTags = ['#outcasttattoo', '#leiria'];
const hashtags = [...styleTags, ...fixedTags].join(' ');

const imageNote = images.length
  ? `Imagens: ${images.join(', ')} (usar imagem 1)`
  : 'Sem imagens';

const prompt = `Escreve uma frase curta (max 15 palavras) em portugues de Portugal para legenda de Instagram, anunciando uma nova tatuagem feita por ${artist} (servico: ${service}). Tom direto e com estilo, sem emojis, sem hashtags. Devolve so a frase, nada mais.`;

return [{
  json: {
    date: dateCompleted,
    artist,
    service,
    hashtags,
    imageLinks: images.join(', '),
    imageNote,
    prompt,
    posted: false,
  },
}];

const item = $('Prepare Prompt').first().json;
const response = $input.first().json;

let line1;
try {
  line1 = response.content[0].text.trim();
} catch (e) {
  // Anthropic call failed or returned unexpected shape — fall back to the plain template
  line1 = `Nova tatuagem por ${item.artist} (${item.service})`;
}

const caption = [line1, item.hashtags, item.imageNote].join('\n');

return [{
  json: {
    date: item.date,
    artist: item.artist,
    caption,
    hashtags: item.hashtags,
    imageLinks: item.imageLinks,
    posted: item.posted,
  },
}];
